fn is_hall_symbol_rhombo(
    shift: &mut Vec3,
    hall_number: i32,
    primitive_lattice: &Mat3,
    symmetry: &Symmetry,
    symprec: f64,
) -> bool {
    if matches!(hall_number, 433 | 436 | 444 | 450 | 452 | 458 | 460) {
        for i in 0..8 {
            if is_hall_symbol(
                shift,
                hall_number,
                primitive_lattice,
                symmetry,
                HallSymbolCandidate {
                    centering: Centering::RCenter,
                    generators: &RHOMBO_H_GENERATORS[i],
                    vspu: &RHOMBO_H_VSPU[i],
                },
                symprec,
            ) {
                return true;
            }
        }
    } else {
        for i in 0..8 {
            if is_hall_symbol(
                shift,
                hall_number,
                primitive_lattice,
                symmetry,
                HallSymbolCandidate {
                    centering: Centering::Primitive,
                    generators: &RHOMBO_P_GENERATORS[i],
                    vspu: &RHOMBO_P_VSPU[i],
                },
                symprec,
            ) {
                return true;
            }
        }
    }
    false
}

